     1→/**
     2→ * YAML file read/write utilities
     3→ */
     4→import { readFile, writeFile, mkdir } from "node:fs/promises";
     5→import { existsSync } from "node:fs";
     6→import { dirname } from "node:path";
     7→import { parse, stringify } from "yaml";
     8→
     9→/**
    10→ * Read and parse a YAML file
    11→ * Returns undefined if file doesn't exist
    12→ */
    13→export async function readYaml<T>(path: string): Promise<T | undefined> {
    14→  try {
    15→    if (!existsSync(path)) {
    16→      return undefined;
    17→    }
    18→    const content = await readFile(path, "utf-8");
    19→    return parse(content) as T;
    20→  } catch (error) {
    21→    console.error(`Failed to read YAML file: ${path}`, error);
    22→    return undefined;
    23→  }
    24→}
    25→
    26→/**
    27→ * Write data to a YAML file
    28→ * Creates parent directories if they don't exist
    29→ */
    30→export async function writeYaml<T>(path: string, data: T): Promise<void> {
    31→  const dir = dirname(path);
    32→  if (!existsSync(dir)) {
    33→    await mkdir(dir, { recursive: true });
    34→  }
    35→  const content = stringify(data, { indent: 2 });
    36→  await writeFile(path, content, "utf-8");
    37→}
    38→
    39→/**
    40→ * Read and parse a JSON file
    41→ * Returns undefined if file doesn't exist
    42→ */
    43→export async function readJson<T>(path: string): Promise<T | undefined> {
    44→  try {
    45→    if (!existsSync(path)) {
    46→      return undefined;
    47→    }
    48→    const content = await readFile(path, "utf-8");
    49→    return JSON.parse(content) as T;
    50→  } catch (error) {
    51→    console.error(`Failed to read JSON file: ${path}`, error);
    52→    return undefined;
    53→  }
    54→}
    55→
    56→/**
    57→ * Write data to a JSON file
    58→ * Creates parent directories if they don't exist
    59→ */
    60→export async function writeJson<T>(path: string, data: T): Promise<void> {
    61→  const dir = dirname(path);
    62→  if (!existsSync(dir)) {
    63→    await mkdir(dir, { recursive: true });
    64→  }
    65→  const content = JSON.stringify(data, null, 2);
    66→  await writeFile(path, content, "utf-8");
    67→}
    68→
    69→/**
    70→ * Ensure a directory exists
    71→ */
    72→export async function ensureDir(path: string): Promise<void> {
    73→  if (!existsSync(path)) {
    74→    await mkdir(path, { recursive: true });
    75→  }
    76→}
    77→
    78→/**
    79→ * Check if a file exists
    80→ */
    81→export function fileExists(path: string): boolean {
    82→  return existsSync(path);
    83→}
