   706→const BASE_URL = "https://api.lighter.xyz";
   707→
   708→export const lighterExchange: Exchange = {
   709→  id: "lighter",
   710→  name: "Lighter",
   711→  fields: ["api_key", "secret"],
   712→  referral_url: "https://lighter.xyz",
   713→  api_doc_url: "https://docs.lighter.xyz",
   714→
   715→  sign(credentials: Credentials, params: SignParams): SignedRequest {
   716→    const { method, path, body } = params;
   717→    const timestamp = params.timestamp;
   718→    const prehash = timestamp + method + path + (body ?? "");
   719→    const signature = createHmac("sha256", credentials.secret)
   720→      .update(prehash)
   721→      .digest("hex");
   722→
   723→    return {
   724→      url: BASE_URL + path,
   725→      headers: {
   726→        "X-API-KEY": credentials.api_key,
   727→        "X-API-SIGNATURE": signature,
   728→        "X-API-TIMESTAMP": timestamp,
   729→        "Content-Type": "application/json",
   730→      },
   731→    };
   732→  },
   733→
   734→  async testConnection(credentials: Credentials): Promise<TestResult> {
   735→    const timestamp = Date.now().toString();
   736→    const path = "/api/v1/account";
   737→    const signed = this.sign(credentials, { method: "GET", path, timestamp });
   738→
   739→    const start = Date.now();
   740→    try {
   741→      const res = await fetch(signed.url, { method: "GET", headers: signed.headers, signal: AbortSignal.timeout(10_000) });
   742→      const latency_ms = Date.now() - start;
   743→      if (res.ok) return { success: true, latency_ms };
   744→      const text = await res.text();
   745→      return { success: false, error: text || `HTTP ${res.status}`, latency_ms };
   746→    } catch (e) {
   747→      return { success: false, error: e instanceof Error ? e.message : "Network error", latency_ms: Date.now() - start };
   748→    }
   749→  },
   750→};
