   816→// packages/core/src/account/ops/crud.ts
   817→
   818→import { nanoid } from "nanoid";
   819→import { readAccounts, writeAccounts, maskCredential } from "./store";
   820→import { getExchange } from "./exchanges";
   821→import type {
   822→  ExchangeId,
   823→  CredentialField,
   824→  Account,
   825→  AccountRecord,
   826→  CreateAccountResult,
   827→  UpdateAccountResult,
   828→  ListAccountsResult,
   829→  ViewAccountResult,
   830→  RemoveAccountResult,
   831→} from "./types";
   832→
   833→const MAX_NAME_LENGTH = 64;
   834→const MAX_CREDENTIAL_LENGTH = 256;
   835→
   836→function validateCredential(value: string, field: string): string | null {
   837→  const trimmed = value.trim();
   838→  if (!trimmed) return `${field} cannot be empty`;
   839→  if (trimmed.length > MAX_CREDENTIAL_LENGTH) return `${field} exceeds max length (${MAX_CREDENTIAL_LENGTH})`;
   840→  return null;
   841→}
   842→
   843→function validateName(name: string): string | null {
   844→  const trimmed = name.trim();
   845→  if (!trimmed) return "name cannot be empty";
   846→  if (trimmed.length > MAX_NAME_LENGTH) return `name exceeds max length (${MAX_NAME_LENGTH})`;
   847→  return null;
   848→}
   849→
   850→function toAccount(record: AccountRecord): Account {
   851→  return {
   852→    id: record.id,
   853→    exchange: record.exchange,
   854→    name: record.name,
   855→    created_at: record.created_at,
   856→    updated_at: record.updated_at,
   857→  };
   858→}
   859→
   860→export async function findAccount(idOrName: string): Promise<AccountRecord | null> {
   861→  const accounts = await readAccounts();
   862→  // 1. Match by ID
   863→  const byId = accounts.find((a) => a.id === idOrName);
   864→  if (byId) return byId;
   865→  // 2. Match by name (exact, case-sensitive)
   866→  const byName = accounts.filter((a) => a.name === idOrName);
   867→  if (byName.length === 1) return byName[0];
   868→  if (byName.length > 1) return null; // ambiguous
   869→  return null;
   870→}
   871→
   872→export async function listAccounts(): Promise<ListAccountsResult> {
   873→  const accounts = await readAccounts();
   874→  return { success: true, accounts: accounts.map(toAccount) };
   875→}
   876→
   877→export async function addAccount(input: {
   878→  exchange: ExchangeId;
   879→  name: string;
   880→  api_key: string;
   881→  secret: string;
   882→  passphrase?: string;
   883→}): Promise<CreateAccountResult> {
   884→  // Validate
   885→  const nameErr = validateName(input.name);
   886→  if (nameErr) return { success: false, error: nameErr };
   887→
   888→  const keyErr = validateCredential(input.api_key, "api_key");
   889→  if (keyErr) return { success: false, error: keyErr };
   890→
   891→  const secretErr = validateCredential(input.secret, "secret");
   892→  if (secretErr) return { success: false, error: secretErr };
   893→
   894→  const exchange = getExchange(input.exchange);
   895→  if (exchange.fields.includes("passphrase")) {
   896→    if (!input.passphrase) return { success: false, error: "passphrase is required for " + exchange.name };
   897→    const ppErr = validateCredential(input.passphrase, "passphrase");
   898→    if (ppErr) return { success: false, error: ppErr };
   899→  }
   900→
   901→  const now = new Date().toISOString();
   902→  const record: AccountRecord = {
   903→    id: nanoid(12),
   904→    exchange: input.exchange,
   905→    name: input.name.trim(),
   906→    api_key: input.api_key.trim(),
   907→    secret: input.secret.trim(),
   908→    passphrase: input.passphrase?.trim(),
   909→    created_at: now,
   910→    updated_at: now,
   911→  };
   912→
   913→  const accounts = await readAccounts();
   914→  accounts.push(record);
   915→  await writeAccounts(accounts);
   916→
   917→  return { success: true, account: toAccount(record) };
   918→}
   919→
   920→export async function viewAccount(idOrName: string): Promise<ViewAccountResult> {
   921→  const record = await findAccount(idOrName);
   922→  if (!record) {
   923→    // Check if ambiguous name
   924→    const accounts = await readAccounts();
   925→    const byName = accounts.filter((a) => a.name === idOrName);
   926→    if (byName.length > 1) {
   927→      return { success: false, error: `Multiple accounts match name "${idOrName}". Use account ID instead.` };
   928→    }
   929→    return { success: false, error: `Account not found: ${idOrName}` };
   930→  }
   931→
   932→  const exchange = getExchange(record.exchange);
   933→  const masked: Partial<Record<CredentialField, string>> = {};
   934→  for (const field of exchange.fields) {
   935→    const value = record[field as keyof AccountRecord] as string | undefined;
   936→    if (value) masked[field] = maskCredential(value);
   937→  }
   938→
   939→  return { success: true, account: toAccount(record), masked_credentials: masked };
   940→}
   941→
   942→export async function updateAccount(idOrName: string, input: {
   943→  name?: string;
   944→  api_key?: string;
   945→  secret?: string;
   946→  passphrase?: string;
   947→}): Promise<UpdateAccountResult> {
   948→  const accounts = await readAccounts();
   949→  const idx = accounts.findIndex((a) => a.id === idOrName || a.name === idOrName);
   950→  if (idx === -1) return { success: false, error: `Account not found: ${idOrName}` };
   951→
   952→  const record = accounts[idx];
   953→
   954→  if (input.name) {
   955→    const nameErr = validateName(input.name);
   956→    if (nameErr) return { success: false, error: nameErr };
   957→    record.name = input.name.trim();
   958→  }
   959→  if (input.api_key) {
   960→    const err = validateCredential(input.api_key, "api_key");
   961→    if (err) return { success: false, error: err };
   962→    record.api_key = input.api_key.trim();
   963→  }
   964→  if (input.secret) {
   965→    const err = validateCredential(input.secret, "secret");
   966→    if (err) return { success: false, error: err };
   967→    record.secret = input.secret.trim();
   968→  }
   969→  if (input.passphrase !== undefined) {
   970→    if (input.passphrase) {
   971→      const err = validateCredential(input.passphrase, "passphrase");
   972→      if (err) return { success: false, error: err };
   973→      record.passphrase = input.passphrase.trim();
   974→    } else {
   975→      record.passphrase = undefined;
   976→    }
   977→  }
   978→
   979→  record.updated_at = new Date().toISOString();
   980→  accounts[idx] = record;
   981→  await writeAccounts(accounts);
   982→
   983→  return { success: true, account: toAccount(record) };
   984→}
   985→
   986→export async function removeAccount(idOrName: string): Promise<RemoveAccountResult> {
   987→  const accounts = await readAccounts();
   988→  const idx = accounts.findIndex((a) => a.id === idOrName || a.name === idOrName);
   989→  if (idx === -1) return { success: false, error: `Account not found: ${idOrName}` };
   990→
   991→  accounts.splice(idx, 1);
   992→  await writeAccounts(accounts);
   993→
   994→  return { success: true };
   995→}
   996→```
