  1283→
  1284→export function registerAccountsRoutes(fastify: FastifyInstance): void {
  1285→  // GET /api/exchanges — exchange registry (static meta)
  1286→  fastify.get("/api/exchanges", async () => {
  1287→    const exchanges = listExchanges();
  1288→    return {
  1289→      exchanges: exchanges.map((ex) => ({
  1290→        id: ex.id,
  1291→        name: ex.name,
  1292→        fields: ex.fields,
  1293→        referral_url: ex.referral_url,
  1294→        api_doc_url: ex.api_doc_url,
  1295→        whitelist_ip: ex.whitelist_ip,
  1296→      })),
  1297→    };
  1298→  });
  1299→
  1300→  // GET /api/accounts — list all (no credentials)
  1301→  fastify.get("/api/accounts", async () => {
  1302→    const result = await listAccounts();
  1303→    return result;
  1304→  });
  1305→
  1306→  // POST /api/accounts — create
  1307→  fastify.post("/api/accounts", async (
  1308→    req: FastifyRequest<{ Body: CreateAccountBody }>,
  1309→    reply,
  1310→  ) => {
  1311→    const { exchange, name, api_key, secret, passphrase } = req.body;
  1312→    if (!exchange || !name || !api_key || !secret) {
  1313→      reply.code(400);
  1314→      return { success: false, error: "exchange, name, api_key, and secret are required" };
  1315→    }
  1316→    const result = await addAccount({ exchange, name, api_key, secret, passphrase });
  1317→    if (!result.success) {
  1318→      reply.code(400);
  1319→      return result;
  1320→    }
  1321→    reply.code(201);
  1322→    return result;
  1323→  });
  1324→
  1325→  // GET /api/accounts/:id — view (masked credentials)
  1326→  fastify.get("/api/accounts/:id", async (
  1327→    req: FastifyRequest<{ Params: { id: string } }>,
  1328→    reply,
  1329→  ) => {
  1330→    const result = await viewAccount(req.params.id);
  1331→    if (!result.success) {
  1332→      reply.code(404);
  1333→      return result;
  1334→    }
  1335→    return result;
  1336→  });
  1337→
  1338→  // PUT /api/accounts/:id — update credentials
  1339→  fastify.put("/api/accounts/:id", async (
  1340→    req: FastifyRequest<{ Params: { id: string }; Body: UpdateAccountBody }>,
  1341→    reply,
  1342→  ) => {
  1343→    const result = await updateAccount(req.params.id, req.body);
  1344→    if (!result.success) {
  1345→      reply.code(result.error?.includes("not found") ? 404 : 400);
  1346→      return result;
  1347→    }
  1348→    return result;
  1349→  });
  1350→
  1351→  // DELETE /api/accounts/:id
  1352→  fastify.delete("/api/accounts/:id", async (
  1353→    req: FastifyRequest<{ Params: { id: string } }>,
  1354→    reply,
  1355→  ) => {
  1356→    const result = await removeAccount(req.params.id);
  1357→    if (!result.success) {
  1358→      reply.code(404);
  1359→      return result;
  1360→    }
  1361→    return result;
  1362→  });
  1363→
  1364→  // POST /api/accounts/:id/test — connectivity test
  1365→  fastify.post("/api/accounts/:id/test", async (
  1366→    req: FastifyRequest<{ Params: { id: string } }>,
  1367→  ) => {
  1368→    const result = await testAccount(req.params.id);
  1369→    return result;
  1370→  });
  1371→}
  1372→```
