     1→/**
     2→ * viben idea - AI-driven idea generation commands
     3→ *
     4→ * Analyzes project codebase to automatically generate improvement suggestions.
     5→ * Supports 6 built-in types and user-defined custom types.
     6→ *
     7→ * Subcommands:
     8→ * - generate: Generate ideas (core command)
     9→ * - list: List generated ideas
    10→ * - list-types: List available idea types (builtin + custom)
    11→ * - view: View idea details
    12→ * - promote: Convert idea to task
    13→ * - remove: Remove ideas
    14→ */
    15→import chalk from "chalk";
    16→import { existsSync, mkdirSync } from "node:fs";
    17→import { join } from "node:path";
    18→import type { Command } from "commander";
    19→import type { OutputContext } from "../types";
    20→import {
    21→  output,
    22→  successResponse,
    23→  outputTable,
    24→  outputKeyValue,
    25→  outputSuccess,
    26→  outputWarning,
    27→  handleCommandError,
    28→} from "../lib";
    29→import { CliError } from "../types";
    30→import { findVibenRoot, DIR_VIBEN, DIR_TASKS } from "../lib/viben-workspace";
    31→import { enqueueTask } from "../../task/ops/lifecycle";
    32→
    33→// Import from idea/ops module
    34→import {
    35→  // Types
    36→  type EffortLevel,
    37→  type IdeaStatus,
    38→  EFFORT_LEVELS,
    39→  IDEA_STATUSES,
    40→  IDEAS_DIR,
    41→  // Store operations
    42→  getIdeasDir,
    43→  // CRUD operations
    44→  listIdeas,
    45→  listTypes,
    46→  viewIdea,
    47→  promoteIdea,
    48→  removeIdeas,
