    53→
    54→// =============================================================================
    55→// Helpers
    56→// =============================================================================
    57→
    58→/**
    59→ * Get output context from program options
    60→ */
    61→function getOutputContext(program: Command): OutputContext {
    62→  const opts = program.opts();
    63→  return {
    64→    json: opts.json ?? false,
    65→    verbose: opts.verbose ?? false,
    66→    quiet: opts.quiet ?? false,
    67→  };
    68→}
    69→
    70→/**
    71→ * Check if the .viben directory exists and return the repo root
    72→ */
    73→function ensureVibenRoot(cwd: string): string {
    74→  const repoRoot = findVibenRoot(cwd);
    75→  if (!repoRoot) {
    76→    throw CliError.operationFailed(
    77→      "Idea command",
    78→      `Not a Viben workspace (.viben not found). Run "viben init" first.`
    79→    );
    80→  }
    81→  return repoRoot;
    82→}
    83→
    84→/**
    85→ * Ensure ideas directory exists
    86→ */
    87→function ensureIdeasDirExists(repoRoot: string): string {
    88→  const ideasDir = getIdeasDir(repoRoot);
    89→  if (!existsSync(ideasDir)) {
    90→    mkdirSync(ideasDir, { recursive: true });
    91→  }
    92→  return ideasDir;
    93→}
    94→
    95→/**
    96→ * Format status for display
    97→ */
    98→function formatStatus(status: string): string {
    99→  switch (status) {
   100→    case "draft":
   101→      return chalk.yellow(status);
   102→    case "promoted":
   103→      return chalk.green(status);
   104→    case "dismissed":
   105→      return chalk.gray(status);
   106→    default:
   107→      return chalk.gray(status);
   108→  }
   109→}
   110→
   111→/**
   112→ * Format effort for display
   113→ */
   114→function formatEffort(effort: string): string {
   115→  switch (effort) {
   116→    case "trivial":
   117→      return chalk.green(effort);
   118→    case "small":
   119→      return chalk.cyan(effort);
   120→    case "medium":
   121→      return chalk.yellow(effort);
   122→    case "large":
   123→      return chalk.red(effort);
   124→    case "complex":
   125→      return chalk.magenta(effort);
   126→    default:
   127→      return chalk.gray(effort);
   128→  }
   129→}
