   374→// ─── Location URL Conversion (formerly location.ts) ──────────────────────────
   375→// @deprecated — These functions are kept only for persist migration and legacy compat.
   376→// New code should use registry.build() / registry.match() from route-registry.ts.
   377→
   378→function decodePathPart(value: string): string {
   379→  try { return decodeURIComponent(value); } catch { return value; }
   380→}
   381→
   382→function extractWorkspacePageSlug(path: string): string | null {
   383→  const pageMatch = path.match(/^\/workspace\/([^/]+)\/page\/(.+)$/);
   384→  if (!pageMatch) return null;
   385→  return pageMatch[2].split("/").map(decodePathPart).join("/");
   386→}
   387→
   388→function extractLegacyPageSlug(rawPagePath: string | null): string | null {
   389→  if (!rawPagePath) return null;
   390→  const pagePath = decodePathPart(rawPagePath);
   391→  const match = pagePath.match(/^pages\/(.+)\/SKILL\.md$/);
   392→  if (match) return match[1];
   393→  if (pagePath.startsWith("pages/")) {
   394→    return pagePath.slice("pages/".length).replace(/\/SKILL\.md$/, "");
   395→  }
   396→  return null;
   397→}
   398→
   399→function normalizeSearch(search?: string): string {
   400→  if (!search) return "";
   401→  return search.startsWith("?") ? search : `?${search}`;
   402→}
   403→
   404→function normalizeHash(hash?: string): string {
   405→  if (!hash) return "";
   406→  return hash.startsWith("#") ? hash : `#${hash}`;
   407→}
   408→
   409→function appendUrlSuffix(path: string, location: LocationUrlSuffix): string {
   410→  const search = normalizeSearch(location.search);
   411→  const hash = normalizeHash(location.hash);
   412→  if (!search) return `${path}${hash}`;
   413→  if (path.includes("?")) return `${path}&${search.slice(1)}${hash}`;
   414→  return `${path}${search}${hash}`;
   415→}
   416→
   417→function buildDetailQuery(
   418→  workspacePath: string | undefined,
   419→  extraParams?: Record<string, string | undefined>
   420→): string {
   421→  const params = new URLSearchParams();
   422→  if (workspacePath) params.set("workspace_path", workspacePath);
   423→  if (extraParams) {
   424→    Object.entries(extraParams).forEach(([key, value]) => {
   425→      if (value) params.set(key, value);
   426→    });
   427→  }
   428→  const query = params.toString();
   429→  return query ? `?${query}` : "";
   430→}
   431→
   432→/** @deprecated Use registry.build() instead — kept only for persist migration in tab-store */
   433→export function locationToUrl(location: DesktopLocation): string {
   434→  switch (location.kind) {
   435→    case "workspace-home":
   436→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}`, location);
   437→    case "workspace-section":
   438→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/${location.section}`, location);
   439→    case "workspace-agent-detail":
   440→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/agent/${encodeURIComponent(location.agentId)}`, location);
   441→    case "workspace-executor-detail":
   442→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/executor/${encodeURIComponent(location.executorType)}`, location);
   443→    case "workspace-page": {
   444→      const encodedSlug = location.pageSlug.split("/").filter(Boolean).map((segment) => encodeURIComponent(segment)).join("/");
   445→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/page/${encodedSlug}`, location);
   446→    }
   447→    case "workspace-web": {
   448→      const params = new URLSearchParams({ url: location.url, title: location.title });
   449→      if (location.sourcePageSlug) params.set("source_page", location.sourcePageSlug);
   450→      if (location.webId) params.set("web_id", location.webId);
   451→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/web?${params.toString()}`, location);
   452→    }
   453→    case "agent-detail":
   454→      return appendUrlSuffix(`/agent/${encodeURIComponent(location.agentId)}${buildDetailQuery(location.workspacePath)}`, location);
   455→    case "executor-detail":
   456→      return appendUrlSuffix(`/executor/${encodeURIComponent(location.executorType)}${buildDetailQuery(location.workspacePath)}`, location);
   457→    case "skill-detail":
   458→      return appendUrlSuffix(`/skill/${encodeURIComponent(location.skillId)}${buildDetailQuery(location.workspacePath, { agent_id: location.agentId })}`, location);
   459→    case "mcp-server-detail":
   460→      return appendUrlSuffix(`/mcp-server/${encodeURIComponent(location.serverName)}${buildDetailQuery(location.workspacePath, { executor_type: location.executorType })}`, location);
   461→    case "subagent-detail":
   462→      return appendUrlSuffix(`/subagent/${encodeURIComponent(location.configId)}${buildDetailQuery(location.workspacePath, { executor_type: location.executorType })}`, location);
   463→    case "prompt-detail":
   464→      return appendUrlSuffix(`/prompt/${encodeURIComponent(location.promptId)}${buildDetailQuery(location.workspacePath, { executor_type: location.executorType })}`, location);
   465→    case "command-detail":
   466→      return appendUrlSuffix(`/command/${encodeURIComponent(location.commandId)}${buildDetailQuery(location.workspacePath, { executor_type: location.executorType })}`, location);
   467→    case "settings":
   468→      return appendUrlSuffix(location.section ? `/settings/${encodeURIComponent(location.section)}` : "/settings/general", location);
   469→    case "documents":
   470→      return appendUrlSuffix("/documents", location);
   471→    case "device-pair":
   472→      return appendUrlSuffix("/devices/pair", location);
   473→    case "global-route":
   474→      return location.path;
   475→    default: {
   476→      const exhaustive: never = location;
   477→      return exhaustive;
   478→    }
   479→  }
   480→}
